const NAV=[['home','Home',Heart],['chat','Chat',MessageCircle],['us','Us',Sparkles],['memories','Memories',Camera],['songs','Our Songs',Music],['letters','Open When',Gift],['journal','Journal',BookHeart],['play','Play Together',Activity],['bucket','Bucket List',Check],['timeline','Our Timeline',Clock],['map','Love Map',MapPin],['settings','Settings',Settings]];
