const GAMES=[['This or That','Quick choices, no overthinking.'],['How Well Do You Know Me?','Make a guess, then find out.'],['Would You Rather','The important questions, obviously.'],['Truth or Dare','Keep it cute. Keep it curious.'],['20 Questions','Think of a thing. Let them guess.'],['Emoji Guess','Decode a tiny story together.'],['Relationship Trivia','How well do you remember?'],['Guess My Answer','Answer, then compare together.']];
