const DATE_CATEGORIES={'At home':['Choose a new recipe and cook it together.','Build a blanket fort and watch a comfort film.'],'Outdoors':['Take a thermos somewhere with a view and watch the light change.','Pick a new trail and bring snacks for the halfway point.'],'Movie':['Pick a film neither of you has seen and make a little snack board.'],'Food':['Visit a weekend market and choose ingredients for dinner.'],'Games':['Choose a co-op game neither of you has played before.'],'Budget-friendly':['Go for a walk with no destination and stop wherever looks lovely.'],'Special occasion':['Dress up for dinner somewhere you have both wanted to try.']};const DATES=Object.values(DATE_CATEGORIES).flat();
